#[cfg(test)]
mod custom_matmul {
    use super::*;
    static FUNC: &str = "custom_matmul";

    #[test]
    fn test_batched_matmul() {
        crate::specify_test!("test_batched_matmul");

        let mut device = TESTCFG.device.clone();
        device.set_default_order(RowMajor);

        // stacked (batched) matmul: (2,2,2) @ (2,2) broadcasts over the leading axis.
        // m12 = [[[1,2],[3,4]], [[1,0],[1,1]]]; matmul(m12, m1) per-slice.
        let m1 = rt::tensor_from_nested!([[1, 2], [3, 4]], &device);
        let m12 = rt::tensor_from_nested!([[[1, 2], [3, 4]], [[1, 0], [1, 1]]], &device);
        // matmul(m12, m1) -> stack([matmul(m1,m1), matmul(m2,m1)])
        //   matmul(m1,m1) = [[7,10],[15,22]]; matmul(m2,m1) = [[1,2],[4,6]]
        let res = rt::matmul(&m12, &m1);
        let expected = rt::tensor_from_nested!([[[7, 10], [15, 22]], [[1, 2], [4, 6]]], &device);
        assert_equal(&res, &expected, None);
    }
}
